  const user = await requireUser();
  await db.project.deleteMany({ where: { id: projectId, userId: user.id } });
  revalidatePath("/dashboard/projects");
}

export async function assignServerProject(serverId: string, projectId: string | null) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
  if (projectId) {
    const project = await db.project.findFirst({ where: { id: projectId, userId: server.userId } });
    if (!project) throw new Error("Project not found");
  }
  await db.server.update({ where: { id: serverId }, data: { projectId } });
  revalidatePath(`/dashboard/servers/${serverId}`);
}

