"use server";

import { redirect } from "next/navigation";
import { db } from "./db";
import { requireUser, destroySession } from "./auth";

/**
 * GDPR self-service actions: account deletion and an export summary for the UI.
 *
 * Everything here is strictly scoped to the *current* signed-in user — a caller
 * can only ever act on their own account. No secrets are read or returned.
 */

/** Servers that still exist for a user (anything not already being torn down). */
async function activeServerCount(userId: string): Promise<number> {
  return db.server.count({ where: { userId, status: { not: "DELETING" } } });
}

export type ExportSummary = {
  activeServers: number;
  walletTransactions: number;
  invoices: number;
  domains: number;
  tickets: number;
  sshKeys: number;
  memberships: number;
};

/** Lightweight counts for the "Privacy & data" UI. Own account only. */
export async function exportSummary(userId: string): Promise<ExportSummary> {
  const user = await requireUser();
  if (user.id !== userId) throw new Error("Forbidden");

  const [activeServers, walletTransactions, invoices, domains, tickets, sshKeys, memberships] =
    await Promise.all([
      activeServerCount(user.id),
      db.walletTransaction.count({ where: { userId: user.id } }),
      db.invoice.count({ where: { userId: user.id } }),
      db.domain.count({ where: { userId: user.id } }),
      db.ticket.count({ where: { userId: user.id } }),
      db.sshKey.count({ where: { userId: user.id } }),
      db.membership.count({ where: { userId: user.id } }),
    ]);

  return { activeServers, walletTransactions, invoices, domains, tickets, sshKeys, memberships };
}

/**
 * Permanently delete the caller's own account.
 *
 * Guard: the user must type their exact email, and must have NO active server
 * (any server with a status other than DELETING). They have to delete their
 * servers first — we refuse otherwise so no live VM is orphaned.
 *
 * The `User` row is removed inside a transaction. Relations that don't cascade
 * at the DB level (servers, wallet transactions, audit logs, referrals) are
 * cleaned up manually first; the rest cascade from `user.delete`. The deletion
 * is audit-logged with `userId: null` before the user disappears.
 */
export async function deleteMyAccount(confirmEmail: string): Promise<{ error?: string }> {
  const user = await requireUser();

  const typed = (confirmEmail ?? "").trim().toLowerCase();
  if (!typed) return { error: "Type your email to confirm." };
  if (typed !== user.email.toLowerCase()) {
    return { error: "That email doesn't match your account." };
  }

  const active = await activeServerCount(user.id);
  if (active > 0) {
    return {
      error: `You still have ${active} active server${active === 1 ? "" : "s"}. Delete ${
        active === 1 ? "it" : "them"
      } first, then close your account.`,
    };
  }

  await db.$transaction([
    // Record the deletion with no owning user (survives the cascade).
    db.auditLog.create({
      data: {
        userId: null,
        action: "user.account_deleted",
        detail: `${user.email} (${user.id}) — self-service GDPR deletion`,
      },
    }),
    // AuditLog.user has no cascade: anonymize this user's remaining trail.
    db.auditLog.updateMany({ where: { userId: user.id }, data: { userId: null } }),
    // Self-relation has no cascade: detach anyone this user referred.
    db.user.updateMany({ where: { referredById: user.id }, data: { referredById: null } }),
    // WalletTransaction.user has no cascade.
    db.walletTransaction.deleteMany({ where: { userId: user.id } }),
    // Server.user has no cascade. Past the guard only DELETING rows remain;
    // removing them cascades jobs, port forwards, dedicated IPs, claude builds, etc.
    db.server.deleteMany({ where: { userId: user.id } }),
    // PasswordResetToken has no FK relation — hygiene only.
    db.passwordResetToken.deleteMany({ where: { userId: user.id } }),
    // Cascades: projects, ssh keys, tickets, notifications, domains, invoices,
    // api tokens, memberships, owned orgs, coupon redemptions; feedback & gift
    // codes are set-null by the schema.
    db.user.delete({ where: { id: user.id } }),
  ]);

  await destroySession();
  redirect("/");
}

import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";

/**
 * GDPR data export — a JSON download of the caller's OWN data.
 *
 *   GET /api/account/export  ->  nxeon-data-export.json (attachment)
 *
 * Strictly scoped to the current user. Secret/credential fields are never
 * included: passwordHash, rootPassword, totpSecret, backupCodes, transferEpp
 * (domain auth code), anthropicKeyEnc, api-token hashes, Stripe ids.
 */
export const dynamic = "force-dynamic";

// Defensive: Prisma BigInt columns (e.g. server bandwidth) aren't JSON-native.
function jsonReplacer(_key: string, value: unknown) {
  return typeof value === "bigint" ? value.toString() : value;
}

export async function GET() {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const [servers, walletTransactions, invoices, domains, tickets, sshKeys, feedback, memberships] =
    await Promise.all([
      db.server.findMany({
        where: { userId: user.id },
        orderBy: { createdAt: "desc" },
        select: {
          id: true,
          name: true,
          label: true,
          hostname: true,
          status: true,
          ipAddress: true,
          ipv6: true,
          sshPort: true,
          isFree: true,
          autoRenew: true,
          termMonths: true,
          addons: true,
          expiresAt: true,
          createdAt: true,
          plan: { select: { slug: true, name: true, priceCents: true } },
          osTemplate: { select: { slug: true, name: true } },
          // rootPassword intentionally excluded.
        },
      }),
      db.walletTransaction.findMany({
        where: { userId: user.id },
        orderBy: { createdAt: "desc" },
      }),
      db.invoice.findMany({
        where: { userId: user.id },
        orderBy: { createdAt: "desc" },
      }),
      db.domain.findMany({
        where: { userId: user.id },
        orderBy: { createdAt: "desc" },
        select: {
          id: true,
          name: true,
          status: true,
          registrar: true,
          priceCents: true,
          termYears: true,
          autoRenew: true,
          nameservers: true,
          whoisPrivacy: true,
          registeredAt: true,
          expiresAt: true,
          createdAt: true,
          // transferEpp (auth code) intentionally excluded.
        },
      }),
      db.ticket.findMany({
        where: { userId: user.id },
        orderBy: { createdAt: "desc" },
        select: {
          id: true,
          subject: true,
          status: true,
          priority: true,
          createdAt: true,
          updatedAt: true,
          messages: {
            orderBy: { createdAt: "asc" },
            select: { id: true, body: true, isStaff: true, createdAt: true },
          },
        },
      }),
      db.sshKey.findMany({
        where: { userId: user.id },
        orderBy: { createdAt: "desc" },
        select: { id: true, name: true, publicKey: true, createdAt: true },
      }),
      db.feedback.findMany({
        where: { userId: user.id },
        orderBy: { createdAt: "desc" },
        select: { id: true, kind: true, title: true, body: true, url: true, status: true, createdAt: true },
      }),
      db.membership.findMany({
        where: { userId: user.id },
        orderBy: { createdAt: "desc" },
        select: {
          id: true,
          role: true,
          createdAt: true,
          org: { select: { id: true, name: true } },
        },
      }),
    ]);

  const profile = {
    id: user.id,
    email: user.email,
    name: user.name,
    role: user.role,
    balanceCents: user.balanceCents,
    suspended: user.suspended,
    createdAt: user.createdAt,
    referralCode: user.referralCode,
    signupCreditCents: user.signupCreditCents,
    totpEnabled: user.totpEnabled,
    autoRechargeEnabled: user.autoRechargeEnabled,
    notificationPrefs: user.notificationPrefs,
    // Excluded secrets: passwordHash, totpSecret, backupCodes, anthropicKeyEnc,
    // stripeCustomerId, stripePaymentMethodId.
  };

  const payload = {
    exportedAt: new Date().toISOString(),
    profile,
    servers,
    walletTransactions,
    invoices,
    domains,
    tickets,
    sshKeys,
    feedback,
    memberships,
  };

  return new NextResponse(JSON.stringify(payload, jsonReplacer, 2), {
    status: 200,
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Content-Disposition": 'attachment; filename="nxeon-data-export.json"',
      "Cache-Control": "private, no-store",
    },
  });
}

"use client";

import { useState, useTransition } from "react";
import { deleteMyAccount } from "@/lib/actions-gdpr";

/**
 * "Privacy & data" card — GDPR data export + self-service account deletion.
 * Deletion requires typing the exact account email to confirm; the server
 * action additionally refuses while any active server exists and, on success,
 * destroys the session and redirects home.
 */
export function DangerZone({ email }: { email: string }) {
  const [confirming, setConfirming] = useState(false);
  const [typed, setTyped] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const matches = typed.trim().toLowerCase() === email.toLowerCase();

  const del = () => {
    if (!matches) return;
    setError(null);
    start(async () => {
      const res = await deleteMyAccount(typed);
      // On success the action redirects away; only errors return here.
      if (res?.error) setError(res.error);
    });
  };

  return (
    <div className="card border-red-500/20">
      <h2 className="mb-1 font-semibold">Privacy &amp; data</h2>
      <p className="mb-5 text-sm text-slate-400">
        Download everything we hold about your account, or permanently close it.
      </p>

      <div className="mb-6">
        <p className="mb-1 text-sm font-medium">Download my data</p>
        <p className="mb-3 text-xs text-slate-500">
          A JSON file with your profile, servers, wallet history, invoices, domains, tickets, SSH
          keys and team memberships. Secrets and passwords are never included.
        </p>
        <a className="btn-secondary inline-flex" href="/api/account/export" download>
          Download my data
        </a>
      </div>

      <hr className="my-6 border-white/[0.06]" />

      <div>
        <p className="mb-1 text-sm font-medium text-red-300">Delete account</p>
        <p className="mb-3 text-xs text-slate-500">
          This permanently erases your account and all associated data. It cannot be undone. You must
          delete all of your servers first.
        </p>

        {!confirming ? (
          <button className="btn-danger" onClick={() => setConfirming(true)}>
            Delete account
          </button>
        ) : (
          <div className="space-y-3 rounded-xl border border-red-500/30 bg-red-500/[0.05] p-4">
            <label className="label">
              Type <span className="font-mono text-red-300">{email}</span> to confirm
            </label>
            <input
              className="input w-full"
              value={typed}
              onChange={(e) => {
                setTyped(e.target.value);
                if (error) setError(null);
              }}
              placeholder={email}
              autoComplete="off"
              spellCheck={false}
            />
            <div className="flex items-center gap-2">
              <button className="btn-danger" disabled={!matches || pending} onClick={del}>
                {pending ? "Deleting…" : "Permanently delete"}
              </button>
              <button
                className="btn-secondary"
                disabled={pending}
                onClick={() => {
                  setConfirming(false);
                  setTyped("");
                  setError(null);
                }}
              >
                Cancel
              </button>
            </div>
            {error && <p className="text-sm text-red-400">{error}</p>}
          </div>
        )}
      </div>
    </div>
  );
}

